const operations = [
  () => set.union(invalid),
  () => set.intersection(invalid),
  () => set.difference(invalid),
  () => set.symmetricDifference(invalid),
  () => set.isSubsetOf(invalid),
  () => set.isSupersetOf(invalid),
  () => set.isDisjointFrom(invalid),
]
